using LealInfoPDV;
using System.Security.Cryptography;
using System.Text.Json.Nodes;
using System.Reflection;
static class Program{
 static void Check(bool yes,string s){if(!yes)throw new Exception(s);Console.WriteLine("PASS "+s);}
 static async Task Grant(AngraSyncTransport t){using var h=new HttpClient();using var req=new HttpRequestMessage(HttpMethod.Get,Environment.GetEnvironmentVariable("ACTIONS_ID_TOKEN_REQUEST_URL")+"&audience="+Uri.EscapeDataString("angra-sync-ci:"+t.DeviceId));req.Headers.Authorization=new("Bearer",Environment.GetEnvironmentVariable("ACTIONS_ID_TOKEN_REQUEST_TOKEN"));var oidc=JsonNode.Parse(await(await h.SendAsync(req)).Content.ReadAsStringAsync())!;using var grant=new HttpRequestMessage(HttpMethod.Post,AngraSyncTransport.Origin+"/sync/ci-grant");grant.Headers.Authorization=new("Bearer",oidc["value"]!.ToString());grant.Content=new StringContent(new JsonObject{["deviceId"]=t.DeviceId,["publicKey"]=t.PublicKey,["role"]="pdv",["bindingOnly"]=true}.ToJsonString(),System.Text.Encoding.UTF8,"application/json");using var r=await h.SendAsync(grant);Check(r.IsSuccessStatusCode,"OIDC isolated expiring test tenant");}
 [STAThread] static void Main(string[] args){Run(args).GetAwaiter().GetResult();}
 static async Task Run(string[] args){Check(Environment.GetEnvironmentVariable("GITHUB_ACTIONS")=="true","disposable Windows");typeof(Auth).GetProperty("Current")!.SetValue(null,new UserSession(1,"QA","qa","ADMINISTRADOR","","",false));Directory.CreateDirectory("pair-evidence");
 if(args[0]=="prepare"){using var key=ECDsa.Create(ECCurve.NamedCurves.nistP256);string pk=Convert.ToBase64String(key.ExportPkcs8PrivateKey());using var transport=new AngraSyncTransport(pk);await Grant(transport);using var service=new AngraPairing(transport);Check(await service.Generate(),"real Windows produces app-compatible ticket");string old=service.Code;Check(await service.Generate()&&service.Code!=old,"renewal produces unique code");Check(service.Expires>DateTimeOffset.UtcNow,"ten minute expiry");File.WriteAllText("pair-evidence/pairing.json",new JsonObject{["privateKey"]=pk,["deviceId"]=transport.DeviceId,["code"]=service.Code,["oldCode"]=old,["channel"]=args[1]}.ToJsonString());return;}
 if(args[0]=="verify"){var data=JsonNode.Parse(File.ReadAllText("pair-evidence/pairing.json"))!;using var transport=new AngraSyncTransport(data["privateKey"]!.ToString());using var service=new AngraPairing(transport);await service.Refresh();Check(service.Status.StartsWith("CONECTADO"),"Windows sees Android native successful pairing");await service.Revoke();Check(service.Status.StartsWith("DESCONECTADO"),"Windows revokes Android link");File.WriteAllText("pair-evidence/verified.txt","PASS Windows ↔ Android actual HTTPS pair, renew, revoke; no operational database initialized");return;}
 throw new Exception("Unknown test phase");
 }
}
